        {
          "url": "https://www.nps.gov/common/uploads/structured_data/60798D9F-974F-C923-0C99B0DB97F2BF2C.jpg",
          "title": "Waring Ranch",
          "altText": "Looking across a long narrow stockpond. Green grass slopes towards the water.",
